/* ===========================
   Bottom Fixed Navbar
   =========================== */

/* Desktop + Tablet (≥642px): pin to bottom */
@media (min-width: 642px){
  .bottom-fixed-nav{
    position: fixed !important;
    left: 0;
    right: 0;
    bottom: calc(var(--nav-bottom, 24px) + env(safe-area-inset-bottom));
    z-index: 9999;
    margin: 0 !important;
    width: 100% !important;
    display: block !important; /* force visible */
  }

  /* Prevent content overlap (reserve space equal to nav height) */
  #main{
    padding-bottom: var(--nav-reserved, 88px);
  }
}

/* Mobile (≤641px): hide this nav, use mobile one */
@media (max-width: 641px){
  .bottom-fixed-nav{
    position: static !important;
    left: auto; right: auto; bottom: auto;
    display: none !important;
  }
}

