  position: fixed;
  top: 0;
  left: 0;
  width: 100vw;
  height: 100vh;
  background: #000;
  color: #fff;
  font-size: 3rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 999999;
  opacity: 1;
  transition: opacity 0.5s ease;
  pointer-events: all;
}

#custom-preloader.hidden {
  opacity: 0;
  pointer-events: none;
}

#custom-preloader-text span {
  opacity: 0;
  transform: translateY(20px);
  display: inline-block;
  animation: riseUpFade 0.25s cubic-bezier(0.4, 0, 0.2, 1) forwards;
}

@keyframes riseUpFade {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}



